ignals:\", sig)\nprint(\"ai-signals files check done\")\n\n# every epic listing an Investigation in deps has gated_by covering it\ninvs = [e for e, fm in fms.items() if fm['type'] == 'Investigation']\nfor e, ds in deps.items():\n    if 'BRANCH' in e: continue\n    inv_deps = [d for d in ds if d in invs]\n    if inv_deps:\n        g = fms[e].get('gated_by') or ''\n        covered = [t.strip() for t in g.split(',') if t.strip()]\n        un = [d for d in inv_deps if d not in covered]\n        if un: print(\"Investigation dep without gate:\", e, un)\nprint(\"investigation-gate coverage check done\")\nEOF","description":"Validate DAG, gates, counts, ai-signals files"}}],"model":"rits/zai-org/glm-5-3","stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":69899,"output_tokens":0},"context_management":null},"parent_tool_use_id":"chatcmpl-tool-9dff2f9036b28837","agent_id":"a9d6226c814588f52","session_id":"382ccfe0-6ddd-4feb-9959-cd45ee4b4e7a","uuid":"1477d72a-5fa5-458f-bb85-3fce89cea240","timestamp":"2026-10-22T12:22:55.923Z","subagent_type":"general-purpose","task_description":"Revise RHAISTRAT-8003 decomposition"}
